{"file_path":"/app/ars.R","content":"# =====================================================================
# Adaptive Rejection Sampling (ARS) for log-concave univariate densities
# Reference: Gilks, W. R. and Wild, P. (1992). "Adaptive rejection
#            sampling for Gibbs sampling".
# Journal of the Royal Statistical Society, Series C, 41(2), 337-348.
#
# This implementation is modular.  The public interface is:
#
#   ars(density_function, domain, n = 1000)
#     density_function : a vectorized function returning a (possibly
#                        unnormalized) density for a numeric vector.
#     domain            : c(lower, upper) support of the density;
#                         -Inf/Inf are allowed.
#     n                 : number of samples to generate.
#
#   test()             : runs a suite of statistical and unit tests.
# =====================================================================


# ---------------------------------------------------------------------
# 1. Input validation
# ---------------------------------------------------------------------

validate_domain <- function(domain) {
  if (!is.numeric(domain) || length(domain) != 2L || anyNA(domain)) {
    stop("'domain' must be a numeric vector of length 2, e.g. c(lower, upper).",
         call. = FALSE)
  }
  if (domain[1] >= domain[2]) {
    stop("'domain' must satisfy domain[1] < domain[2].", call. = FALSE)
  }
  c(lower = domain[1], upper = domain[2])
}


validate_sample_count <- function(n) {
  if (length(n) != 1L || !is.numeric(n) || is.na(n) ||
      n < 1 || abs(n - round(n)) > 1e-12) {
    stop("'n' must be a single positive integer.", call. = FALSE)
  }
  as.integer(n)
}


validate_density_function <- function(density_function) {
  if (!is.function(density_function)) {
    stop("'density_function' must be a function.", call. = FALSE)
  }
  invisible(TRUE)
}


# ---------------------------------------------------------------------
# 2. Evaluating log-density and numeric derivative
# ---------------------------------------------------------------------

#' log_density
#'
#' Evaluate log(density_function(x)). Values <= 0 are mapped to -Inf
#' (outside the effective support); invalid returns are errors.
log_density <- function(density_function, x) {
  if (length(x) == 0L) return(numeric(0))
  vals <- density_function(x)
  if (!is.numeric(vals)) {
    stop("density_function must return numeric values.", call. = FALSE)
  }
  if (length(vals) == 1L && length(x) > 1L) vals <- rep(vals, length(x))
  if (length(vals) != length(x)) {
    stop("density_function must be vectorized (one value per input).",
         call. = FALSE)
  }
  if (anyNA(vals)) {
    stop("density_function returned NA.", call. = FALSE)
  }
  if (any(vals < 0)) {
    stop("density_function returned a negative density.", call. = FALSE)
  }
  if (any(is.infinite(vals) & vals > 0)) {
    stop("density_function returned Inf.", call. = FALSE)
  }
  out <- rep(-Inf, length(vals))
  ok  <- is.finite(vals) & vals > 0
  out[ok] <- log(vals[ok])
  out
}


#' numeric_gradient
#'
#' Numeric derivative of log-density using central differences when
#' possible and one-sided differences near the support boundary.
numeric_gradient <- function(density_function, x, lower, upper) {
  n <- length(x)
  if (n == 0L) return(numeric(0))
  eps <- 1e-6 * pmax(abs(x), 1)
  deriv <- numeric(n)

  for (i in seq_len(n)) {
    xi <- x[i]
    ei <- eps[i]

    # Central difference if both sides are strictly inside the support
    central <- (xi - ei > lower) && (xi + ei < upper)

    if (central) {
      dplus  <- log_density(density_function, xi + ei)
      dminus <- log_density(density_function, xi - ei)
      if (!is.finite(dplus) || !is.finite(dminus)) {
        central <- FALSE
      } else {
        deriv[i] <- (dplus - dminus) / (2 * ei)
        next
      }
    }

    # One-sided difference.  Choose the side with more room.
    room_lower <- if (is.finite(lower)) xi - lower else Inf
    room_upper <- if (is.finite(upper)) upper - xi else Inf

    if (room_lower <= room_upper) {
      # Forward difference (closer to lower bound)
      hstep <- max(min(2 * ei, room_upper), .Machine$double.eps)
      deriv[i] <- (log_density(density_function, xi + hstep) -
                   log_density(density_function, xi)) / hstep
    } else {
      # Backward difference (closer to upper bound)
      hstep <- max(min(2 * ei, room_lower), .Machine$double.eps)
      deriv[i] <- (log_density(density_function, xi) -
                   log_density(density_function, xi - hstep)) / hstep
    }
  }
  deriv
}


# ---------------------------------------------------------------------
# 3. Abscissae initialisation
# ---------------------------------------------------------------------

#' estimate_mode
#'
#' Approximate the mode of a log-concave density using expansion of a
#' bracket followed by a golden-section/optimize step.
estimate_mode <- function(density_function, lower, upper) {
  logd <- function(x) log_density(density_function, x)

  # Initial search point inside the support
  start <- 0
  if (is.finite(lower) && start < lower) start <- lower
  if (is.finite(upper) && start > upper) start <- upper
  if (!is.finite(start)) start <- 0
  if (is.finite(lower) && start <= lower) {
    start <- lower + min(0.5, if (is.finite(upper)) (upper - lower) / 4 else 1)
  }
  if (is.finite(upper) && start >= upper) {
    start <- upper - min(0.5, if (is.finite(lower)) (upper - lower) / 4 else 1)
  }

  f_start <- logd(start)
  if (!is.finite(f_start)) {
    found <- NULL
    if (is.finite(lower)) {
      span <- if (is.finite(upper)) upper - lower else 1
      cand <- lower + seq(1e-6, 1, length.out = 30) * span
      for (cc in cand) {
        if (is.finite(logd(cc))) {
          found <- cc
          break
        }
      }
    }
    if (is.null(found) && is.finite(upper)) {
      span <- if (is.finite(lower)) upper - lower else 1
      cand <- upper - seq(0.2, 0.01, length.out = 30) * span
      cand <- cand[cand > lower]
      for (cc in cand) {
        if (is.finite(logd(cc))) {
          found <- cc
          break
        }
      }
    }
    if (is.null(found)) {
      stop("no point with positive density was found inside 'domain'.",
           call. = FALSE)
    }
    start <- found
    f_start <- logd(start)
  }

  step <- pmax(abs(start) * 0.1 + 0.5, 1)
  if (is.finite(lower) && is.finite(upper)) {
    step <- min(step, (upper - lower) / 6)
  }

  left  <- start - step
  right <- start + step
  if (is.finite(lower) && left < lower) left <- lower + 1e-8
  if (is.finite(upper) && right > upper) right <- upper - 1e-8

  fl <- logd(left)
  fr <- logd(right)
  if (!is.finite(fl)) fl <- -Inf
  if (!is.finite(fr)) fr <- -Inf

  lo <- left
  hi <- right

  if (is.finite(fr) && fr > f_start && fr >= fl) {
    # Expand to the right until log-density decreases
    lo <- start
    hi <- right
    repeat {
      prev_hi <- hi
      next_hi <- start + (hi - start) * 2 + step
      if (is.finite(upper) && next_hi > upper) next_hi <- upper
      if (next_hi <= prev_hi) break
      f_next <- logd(next_hi)
      if (!is.finite(f_next)) break
      hi <- next_hi
      if (f_next <= logd(prev_hi) + 1e-12) break
      if (abs(hi - start) > 1e7) break
      if (is.finite(upper) && hi >= upper) break
    }
  } else if (is.finite(fl) && fl > f_start && fl >= fr) {
    # Expand to the left
    hi <- start
    lo <- left
    repeat {
      prev_lo <- lo
      next_lo <- start - (start - lo) * 2 - step
      if (is.finite(lower) && next_lo < lower) next_lo <- lower
      if (next_lo >= prev_lo) break
      f_next <- logd(next_lo)
      if (!is.finite(f_next)) break
      lo <- next_lo
      if (f_next <= logd(prev_lo) + 1e-12) break
      if (abs(lo - start) > 1e7) break
      if (is.finite(lower) && lo <= lower) break
    }
  }

  if (!is.finite(lo)) lo <- if (is.finite(lower)) lower else start - 1
  if (!is.finite(hi)) hi <- if (is.finite(upper)) upper else start + 1
  if (lo >= hi) {
    lo <- start - 0.5
    hi <- start + 0.5
  }

  opt <- tryCatch(
    stats::optimize(function(x) logd(x), lower = lo, upper = hi,
                    maximum = TRUE),
    error = function(e) NULL
  )
  if (!is.null(opt) && is.finite(opt$maximum)) {
    return(opt$maximum)
  }
  (lo + hi) / 2
}


#' find_tail_point
#'
#' Find a point on one side of the mode where log-density is
#' h0 - drop.  Returns NA if it cannot be found.
find_tail_point <- function(f, h0, x0, side, drop, lower, upper,
                            max_expand = 1e6) {
  target <- h0 - drop
  dir <- if (side == "right") 1 else -1

  step <- pmax(abs(x0) * 0.1 + 0.1, 1)
  if (is.finite(lower) && is.finite(upper)) {
    step <- min(step, (upper - lower) / 5)
  }

  prev_x <- x0
  prev_f <- f(prev_x)
  cur_x <- x0 + dir * step
  if (is.finite(lower) && cur_x < lower) cur_x <- lower
  if (is.finite(upper) && cur_x > upper) cur_x <- upper
  cur_f <- f(cur_x)

  max_iter <- 80
  for (i in seq_len(max_iter)) {
    if (is.finite(cur_f) && cur_f <= target) break

    if (!is.finite(cur_f)) {
      # Walk inside the boundary until we get a finite value.
      lo <- prev_x
      hi <- cur_x
      for (j in 1:60) {
        mid <- (lo + hi) / 2
        fm <- f(mid)
        if (!is.finite(fm)) {
          hi <- mid
        } else {
          lo <- mid
          if (fm <= target) hi <- mid
        }
      }
      cur_x <- lo
      cur_f <- f(cur_x)
      break
    }

    prev_x <- cur_x
    prev_f <- cur_f
    step <- step * 2
    cur_x <- x0 + dir * step
    if (side == "right" && is.finite(upper) && cur_x >= upper) cur_x <- upper
    if (side == "left"  && is.finite(lower) && cur_x <= lower) cur_x <- lower
    if (abs(cur_x - x0) > max_expand) break
    cur_f <- f(cur_x)
    if (side == "right" && is.finite(upper) && cur_x >= upper) break
    if (side == "left"  && is.finite(lower) && cur_x <= lower) break
  }

  if (!is.finite(prev_f)) prev_f <- f(prev_x)

  # Bisection / root finding for the crossing
  if (is.finite(prev_f) && is.finite(cur_f) &&
      prev_f > target && cur_f <= target && prev_x != cur_x) {
    sol <- tryCatch(
      stats::uniroot(function(t) f(t) - target, c(prev_x, cur_x))$root,
      error = function(e) (prev_x + cur_x) / 2
    )
    if (is.finite(sol)) return(sol)
  }

  if (is.finite(prev_f) && is.finite(cur_f)) {
    return((prev_x + cur_x) / 2)
  }
  if (is.finite(cur_f)) return(cur_x)
  if (is.finite(prev_f)) return(prev_x)
  NA_real_
}


#' initial_abscissae
#'
#' Construct a set of starting abscissae spanning the support. The set
#' includes the (approximate) mode and points in both tails where the
#' log-density has dropped by a sequence of amounts.
initial_abscissae <- function(density_function, lower, upper) {
  logd <- function(x) log_density(density_function, x)

  x0 <- estimate_mode(density_function, lower, upper)
  if (!is.finite(x0)) x0 <- 0

  # Keep the mode strictly inside the support where possible.
  tol <- 1e-9
  if (is.finite(lower) && x0 <= lower + tol) {
    x0 <- lower + min(1e-4, if (is.finite(upper)) (upper - lower) / 10 else 1)
  }
  if (is.finite(upper) && x0 >= upper - tol) {
    x0 <- upper - min(1e-4, if (is.finite(lower)) (upper - lower) / 10 else 1)
  }

  h0 <- logd(x0)
  if (!is.finite(h0)) {
    # Move a little away from the boundary until density is positive.
    for (i in 1:50) {
      delta <- 1e-5 * i
      if (is.finite(lower) && x0 < (upper + lower) / 2) {
        cand <- x0 + delta
      } else {
        cand <- x0 - delta
      }
      if (cand > lower && cand < upper && is.finite(logd(cand))) {
        x0 <- cand
        break
      }
    }
    h0 <- logd(x0)
    if (!is.finite(h0)) {
      stop("could not locate a mode with positive density.", call. = FALSE)
    }
  }

  drops <- c(0.2, 0.7, 2, 6, 15)
  pts <- c(x0)

  for (d in drops) {
    if (lower < x0) {
      p <- find_tail_point(logd, h0, x0, "left", d, lower, upper)
      if (is.finite(p) && p > lower) pts <- c(pts, p)
    }
    if (upper > x0) {
      p <- find_tail_point(logd, h0, x0, "right", d, lower, upper)
      if (is.finite(p) && p < upper) pts <- c(pts, p)
    }
  }

  pts <- sort(unique(pts))

  # Remove points that are too close to a boundary where density is zero
  keep <- rep(TRUE, length(pts))
  if (is.finite(lower)) keep <- keep & (pts > lower + 1e-12)
  if (is.finite(upper)) keep <- keep & (pts < upper - 1e-12)
  pts <- pts[keep]

  if (length(pts) < 2) {
    stop("could not find at least two abscissae with positive density.",
         call. = FALSE)
  }

  h  <- logd(pts)
  hp <- numeric_gradient(density_function, pts, lower, upper)

  keep <- is.finite(h) & is.finite(hp)
  pts <- pts[keep]
  h   <- h[keep]
  hp  <- hp[keep]

  if (length(pts) < 2) {
    stop("could not find at least two abscissae with finite gradient.",
         call. = FALSE)
  }

  list(x = pts, h = h, hp = hp)
}


# ---------------------------------------------------------------------
# 4. The upper hull / envelope
# ---------------------------------------------------------------------

#' check_log_concavity
#'
#' For a log-concave density the tangent slopes must be non-increasing.
#' Raises an informative error if the slopes increase.
check_log_concavity <- function(x, hp, tol = NULL) {
  if (length(x) != length(hp)) {
    stop("internal error: abscissae/gradient length mismatch.", call. = FALSE)
  }
  if (length(x) <= 1L) return(invisible(TRUE))
  if (is.null(tol)) {
    tol <- 1e-6 * max(1, max(abs(hp)))
  }
  d <- diff(hp)
  if (any(d > tol)) {
    idx <- which(d > tol)[1]
    stop(sprintf(paste0(
      "density is not log-concave: tangent slope increases between ",
      "x=%.6g and x=%.6g (slopes %.6g -> %.6g)."
    ), x[idx], x[idx + 1], hp[idx], hp[idx + 1]), call. = FALSE)
  }
  invisible(TRUE)
}


#' tangent_intersection
#'
#' Intersection of the tangent lines at two consecutive abscissae.
tangent_intersection <- function(x1, h1, s1, x2, h2, s2) {
  denom <- s1 - s2
  if (abs(denom) < 1e-300) {
    return((x1 + x2) / 2)
  }
  (h2 - s2 * x2 - h1 + s1 * x1) / denom
}


#' segment_log_area
#'
#' Log of  integral(exp(b + s*(t - xi)), t = l..r).
segment_log_area <- function(b, s, xi, l, r) {
  if (is.finite(l) && is.finite(r) && l >= r) return(-Inf)

  # Left-unbounded interval
  if (is.infinite(l)) {
    if (s <= 0) {
      stop("cannot build a finite envelope over a left-unbounded tail; ",
           "check that the density is log-concave and the abscissae are ",
           "placed correctly.", call. = FALSE)
    }
    return(b + s * (r - xi) - log(s))
  }

  # Right-unbounded interval
  if (is.infinite(r)) {
    if (s >= 0) {
      stop("cannot build a finite envelope over a right-unbounded tail; ",
           "check that the density is log-concave and the abscissae are ",
           "placed correctly.", call. = FALSE)
    }
    return(b + s * (l - xi) - log(-s))
  }

  # Finite interval
  if (abs(s) < 1e-300) {
    return(b + log(r - l))
  }

  A <- b + s * (l - xi)
  B <- b + s * (r - xi)

  if (is.finite(A) && is.finite(B)) {
    if (s > 0) {
      # Integral = exp(B) * (1 - exp(A-B)) / s
      return(B + log(-expm1(A - B)) - log(s))
    } else {
      # Integral = exp(A) * (1 - exp(B-A)) / (-s)
      return(A + log(-expm1(B - A)) - log(-s))
    }
  }

  # Asymptotic fallback (large exponents)
  if (s > 0) {
    return(B + log(if (A > B) -expm1(A - B) else 1) - log(s))
  } else {
    return(A + log(if (B > A) -expm1(B - A) else 1) - log(-s))
  }
}


#' compute_hull
#'
#' Build the piecewise-exponential upper hull from the abscissae and
#' their tangent slopes.
compute_hull <- function(x, h, hp, lower, upper) {
  if (length(x) != length(h) || length(x) != length(hp)) {
    stop("internal error: abscissae/h/gradient length mismatch.", call. = FALSE)
  }
  if (length(x) < 2L) {
    stop("at least two abscissae are required.", call. = FALSE)
  }

  ord <- order(x)
  x  <- x[ord]
  h  <- h[ord]
  hp <- hp[ord]

  # Log-concavity check (slopes must be non-increasing)
  check_log_concavity(x, hp)

  m <- length(x)
  z <- numeric(m + 1)
  z[1] <- lower
  z[m + 1] <- upper

  if (m >= 2L) {
    for (i in seq_len(m - 1L)) {
      z[i + 1] <- tangent_intersection(x[i], h[i], hp[i],
                                       x[i + 1], h[i + 1], hp[i + 1])
    }
  }

  if (any(diff(z) <= 0) || any(!is.finite(z[2:m]))) {
    stop("could not build a valid envelope; the density may not be ",
         "log-concave or the abscissae are badly placed.", call. = FALSE)
  }

  log_areas <- numeric(m)
  for (i in seq_len(m)) {
    log_areas[i] <- segment_log_area(h[i], hp[i], x[i],
                                     z[i], z[i + 1])
  }

  if (any(!is.finite(log_areas))) {
    stop("envelope integral is not finite; check the density is ",
         "log-concave.", call. = FALSE)
  }

  list(x = x, h = h, hp = hp, z = z,
       b = h, s = hp, log_areas = log_areas)
}


#' log_envelope_at
#'
#' Log of the upper hull evaluated at x.
log_envelope_at <- function(hull, x) {
  z <- hull$z
  m <- length(hull$x)
  idx <- findInterval(x, z)
  if (idx < 1L) idx <- 1L
  if (idx > m)  idx <- m
  hull$b[idx] + hull$s[idx] * (x - hull$x[idx])
}


#' log_chord_at
#'
#' Log of the squeezing function (chord interpolation between
#' consecutive abscissae). Returns -Inf outside the current point set.
log_chord_at <- function(xp, hp, x) {
  m <- length(xp)
  if (m < 2L) return(-Inf)
  if (x < xp[1] || x > xp[m]) return(-Inf)

  idx <- findInterval(x, xp)
  idx <- max(idx, 1L)
  idx <- min(idx, m - 1L)

  t <- 0
  denom <- xp[idx + 1] - xp[idx]
  if (denom > 0) t <- (x - xp[idx]) / denom
  t <- max(0, min(t, 1))

  hp[idx] * (1 - t) + hp[idx + 1] * t
}


# ---------------------------------------------------------------------
# 5. Sampling from the envelope
# ---------------------------------------------------------------------

#' sample_segment
#'
#' Inverse-CDF sample from one envelope segment.
sample_segment <- function(hull, i, u) {
  m <- length(hull$x)
  if (i < 1L || i > m) stop("internal error: bad segment index.", call. = FALSE)

  b  <- hull$b[i]
  s  <- hull$s[i]
  xi <- hull$x[i]
  l  <- hull$z[i]
  r  <- hull$z[i + 1]

  if (is.infinite(l) && is.infinite(r)) {
    stop("internal error: envelope segment with two infinite ends.",
         call. = FALSE)
  }

  if (is.infinite(l)) {
    if (s <= 0) stop("internal error: bad left-unbounded segment.", call. = FALSE)
    return(r + log(u) / s)
  }

  if (is.infinite(r)) {
    if (s >= 0) stop("internal error: bad right-unbounded segment.", call. = FALSE)
    return(l + log(1 - u) / s)
  }

  if (abs(s) < 1e-300) {
    return(l + u * (r - l))
  }

  A <- b + s * (l - xi)
  B <- b + s * (r - xi)
  M <- max(A, Bming or finite)
  if (!is.finite(M)) stop("overflow in envelope segment.", call. = FALSE)

  alpha <- exp(A - M) * (1 - u) + exp(B - M) * u
  alpha <- max(alpha, .Machine$double.eps)

  t <- xi + (M + log(alpha) - b) / s
  t <- max(t, l)
  t <- min(t, r)
  t
}


#' sample_envelope
#'
#' Draw one point from the normalized envelope density.
sample_envelope <- function(hull, uv = NULL) {
  log_areas <- hull$log_areas
  m <- length(log_areas)
  if (is.null(uv)) uv <- runif(2)
  u1 <- min(max(uv[1], .Machine$double.eps), 1 - .Machine$double.eps)
  u2 <- min(max(uv[2], .Machine$double.eps), 1 - .Machine$double.eps)

  M <- max(log_areas)
  w <- exp(log_areas - M)
  total <- sum(w)
  target <- u1 * total
  cs <- cumsum(w)
  idx <- which(cs >= target)[1]
  if (is.na(idx)) idx <- m

  x <- sample_segment(hull, idx, u2)
  list(x = x, interval = idx)
}


# ---------------------------------------------------------------------
# 6. Adaptive Rejection Sampler
# ---------------------------------------------------------------------

#' ars
#'
#' Adaptive rejection sampling from an univariate log-concave density.
#'
#' @param density_function vectorized density function (possibly unnormalized)
#' @param domain           c(lower, upper) support
#' @param n                number of samples
#' @return numeric vector of n samples
ars <- function(density_function, domain, n = 1000) {
  bounds <- validate_domain(domain)
  lower  <- bounds[["lower"]]
  upper  <- bounds[["upper"]]
  n      <- validate_sample_count(n)
  validate_density_function(density_function)

  init <- initial_abscissae(density_function, lower, upper)
  x  <- init$x
  h  <- init$h
  hp <- init$hp

  hull <- compute_hull(x, h, hp, lower, upper)

  samples <- numeric(n)
  collected <- 0L
  attempts <- 0L
  max_attempts <- max(5000L, as.integer(n * 200))

  while (collected < n) {
    attempts <- attempts + 1L
    if (attempts > max_attempts) {
      stop(sprintf(paste0(
        "ARS could not generate %d samples after %d attempts; ",
        "the density may not be log-concave."
      ), n, max_attempts), call. = FALSE)
    }

    draw <- sample_envelope(hull)
    xcand <- draw$x
    u <- uv <- NULL
    # Reconstruct uniforms for reproducibility in the test harness is not
    # needed; sample_envelope already used its own uniforms, but we need
    # one for acceptance. Draw a fresh uniform.
    u <- runif(1)

    if (!is.finite(xcand) || is.na(xcand)) next
    if (is.finite(lower) && xcand <= lower) next
    if (is.finite(upper) && xcand >= upper) next

    Ux <- log_envelope_at(hull, xcand)
    if (!is.finite(Ux)) {
      stop("envelope evaluation failed for a candidate.", call. = FALSE)
    }

    Cx <- log_chord_at(hull$x, hull$h, xcand)

    # Squeezing test
    if (is.finite(Cx) && u <= exp(Cx - Ux)) {
      collected <- collected + 1L
      samples[collected] <- xcand
      next
    }

    # Squeeze failed: evaluate the density and its derivative.
    hx <- log_density(density_function, xcand)
    if (!is.finite(hx)) next  # density effectively zero at this point

    hp_new <- numeric_gradient(density_function, xcand, lower, upper)
    if (!is.finite(hp_new)) {
      stop("could not evaluate the derivative of the log-density.",
           call. = FALSE)
    }

    # Add the evaluated point to the abscissae (the adaptive part).
    if (min(abs(x - xcand)) > 1e-12) {
      x  <- c(x, xcand)
      h  <- c(h, hx)
      hp <- c(hp, hp_new)
      ord <- order(x)
      x  <- x[ord]
      h  <- h[ord]
      hp <- hp[ord]

      # This will raise an informative error for non-log-concave densities.
      hull <- compute_hull(x, h, hp, lower, upper)
    }

    # Upper-hull acceptance test (using the hull that produced xcand).
    if (u <= exp(hx - Ux)) {
      collected <- collected + 1L
      samples[collected] <- xcand
    }
    # Otherwise the candidate is rejected and the loop tries again.
  }

  samples
}


