#' check_result
#'
#' Prints "name: PASS" or "name: FAIL" and returns the logical result.
check_result <- function(name, ok, detail = "") {
  tag <- if (isTRUE(ok)) "PASS" else "FAIL"
  cat(sprintf("%s: %s %s\n", name, tag, detail))
  invisible(isTRUE(ok))
}


#' approx_norm_moments
#'
#' Check that a sample mean and sd agree with known values within
#' 4 Monte-Carlo standard errors.
approx_norm_moments <- function(samples, true_mean, true_sd,
                                alpha = 4) {
  n <- length(samples)
  sample_mean <- mean(samples)
  sample_sd   <- stats::sd(samples)
  se_mean <- true_sd / sqrt(n)
  se_sd   <- true_sd / sqrt(2 * (n - 1))

  ok_mean <- abs(sample_mean - true_mean) <= alpha * se_mean
  ok_sd   <- abs(sample_sd - true_sd) <= alpha * se_sd
  list(ok = ok_mean && ok_sd,
       mean = sample_mean, sd = sample_sd,
       ok_mean = ok_mean, ok_sd = ok_sd)
}


